mapper.select:
SELECT * FROM approvals
WHERE work_item_id = #{workItemId} AND status_id = #{statusId}
ORDER BY id

SELECT COUNT(*) FROM approvals
WHERE work_item_id = #{workItemId} AND status_id = #{statusId}
  AND decision = 'PENDING'

SELECT a.* FROM approvals a JOIN work_items w ON w.id = a.work_item_id WHERE w.project_id = #{projectId} AND w.deleted_at IS NULL
AND a.decision = #{decision}
ORDER BY a.id DESC

mapper.update:
UPDATE approvals
SET decision   = #{decision},
    comment    = #{comment},
    decided_by = #{decidedBy},
    decided_at = #{decidedAt}
WHERE id = #{id}
